import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Demo artifacts","description":"","frontmatter":{},"headers":[],"relativePath":"demo-artifacts.md","filePath":"demo-artifacts.md"}'),s={name:"demo-artifacts.md"};function d(n,e,c,r,h,l){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="demo-artifacts" tabindex="-1">Demo artifacts <a class="header-anchor" href="#demo-artifacts" aria-label="Permalink to &quot;Demo artifacts&quot;">​</a></h1><p>The <code>Demo artifacts</code> workflow builds both demo applications for GitHub Pages and publishes them as one immutable artifact. Deploying that artifact to the public site is done by the <code>pidrang.github.io</code> repository, which serves <code>https://pidrang.dev/</code>.</p><h2 id="building-an-artifact" tabindex="-1">Building an artifact <a class="header-anchor" href="#building-an-artifact" aria-label="Permalink to &quot;Building an artifact&quot;">​</a></h2><p>The workflow also runs on pull requests that touch the demos, the libraries or these tools, to check that the Pages build keeps working; those runs upload nothing. Run the workflow manually from the Actions tab (<code>Demo artifacts</code>, Run workflow). Leave <code>ref</code> empty to build the branch you run it from, or pass a branch, tag or commit to build exactly that source. The workflow:</p><ol><li>builds <code>demo-material</code> and <code>demo-tailwind</code> with their <code>pages</code> configuration, which sets the base path (<code>/demo-material/</code>, <code>/demo-tailwind/</code>) and replaces the environment with <code>environment.pages.ts</code> so the links between the demos use the public URLs,</li><li>assembles the artifact and writes <code>metadata.json</code>,</li><li>refuses to continue if the output contains a service role key, a <code>sb_secret_</code> key, a database connection string or a JWT whose role is not <code>anon</code>,</li><li>serves the artifact with a static server that behaves like GitHub Pages and runs the Playwright checks against it,</li><li>uploads the artifact as <code>demos-&lt;commit sha&gt;</code>, kept for 30 days.</li></ol><p>Only the public Supabase URL and the publishable key are in the artifact. Both are already in the repository, and Row Level Security on the demo project is what limits what they can do.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>demos/</span></span>
<span class="line"><span>  metadata.json</span></span>
<span class="line"><span>  404.html</span></span>
<span class="line"><span>  demo-material/</span></span>
<span class="line"><span>  demo-tailwind/</span></span></code></pre></div><p><code>metadata.json</code> records where the artifact comes from:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>schema</code></td><td>Version of this file format, currently <code>1</code>.</td></tr><tr><td><code>source.repository</code>, <code>source.commit</code>, <code>source.ref</code></td><td>Repository, exact commit and ref that were built.</td></tr><tr><td><code>source.dirty</code></td><td><code>true</code> when the working tree had uncommitted changes. An artifact built by the workflow is never dirty.</td></tr><tr><td><code>source.workflow</code>, <code>source.runId</code></td><td>The workflow and run that produced it.</td></tr><tr><td><code>builtAt</code></td><td>Build time, ISO 8601.</td></tr><tr><td><code>origin</code>, <code>demos</code></td><td>Public origin and the path and URL of each demo.</td></tr><tr><td><code>packages</code></td><td>Version of each <code>@pidrang/*</code> library in the source.</td></tr></tbody></table><h2 id="demo-account" tabindex="-1">Demo account <a class="header-anchor" href="#demo-account" aria-label="Permalink to &quot;Demo account&quot;">​</a></h2><p>The sign-in page of the Pages build shows a shared demo account, <code>demo@pidrang.dev</code>, with a button that signs in with it. Its credentials come from <code>demoAccount</code> in each demo&#39;s <code>environment.pages.ts</code> and are public on purpose. Local and development builds do not show it (<code>demoAccount</code> is <code>null</code>).</p><p>The hosted Supabase project keeps sign-ups closed, so the demo account and the team accounts are the only accounts, and a trigger in <code>pidrang/supabase</code> rejects any change to the demo account&#39;s password, email or phone. To change the demo password, follow the README of that repository, then update both <code>environment.pages.ts</code> files.</p><h2 id="deep-links" tabindex="-1">Deep links <a class="header-anchor" href="#deep-links" aria-label="Permalink to &quot;Deep links&quot;">​</a></h2><p>GitHub Pages serves only static files and uses the <code>404.html</code> at the root of the site for any unknown path. A demo cannot have its own. The artifact therefore ships one generic <code>404.html</code> that must be copied to the root of the site.</p><p>For a path such as <code>/demo-material/products/create?x=1#top</code>, it redirects to <code>/demo-material/?/products/create&amp;x=1#top</code>. A small script in each demo&#39;s <code>index.html</code> then restores the original path, query string and hash before Angular starts. Any other unknown path keeps a plain &quot;Page not found&quot; page.</p><h2 id="deploying-it-from-pidrang-github-io" tabindex="-1">Deploying it from <code>pidrang.github.io</code> <a class="header-anchor" href="#deploying-it-from-pidrang-github-io" aria-label="Permalink to &quot;Deploying it from \`pidrang.github.io\`&quot;">​</a></h2><p>The site workflow should, for an explicitly chosen run:</p><ol><li>download the artifact with <code>gh run download &lt;run-id&gt; --repo pidrang/pidrang --name demos-&lt;sha&gt;</code>,</li><li>check with <code>gh run view &lt;run-id&gt; --repo pidrang/pidrang --json workflowName,event,conclusion</code> that the run is the <code>Demo artifacts</code> workflow, was started manually (<code>workflow_dispatch</code>) and succeeded, that <code>source.commit</code> in <code>metadata.json</code> equals the <code>&lt;sha&gt;</code> in the artifact name, and that <code>source.dirty</code> is <code>false</code>,</li><li>copy <code>demo-material/</code>, <code>demo-tailwind/</code> and <code>404.html</code> into the site, next to the existing landing page files,</li><li>keep <code>metadata.json</code> at the site root so the deployed source stays traceable.</li></ol><p>To roll back, deploy the previous run the same way, or revert the deployment commit in the site repository. Artifacts expire after 30 days, so a revert is the way back for older deployments.</p><h2 id="running-the-checks-locally" tabindex="-1">Running the checks locally <a class="header-anchor" href="#running-the-checks-locally" aria-label="Permalink to &quot;Running the checks locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/demo-artifacts/build.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/demo-artifacts/playwright.config.mts</span></span></code></pre></div><p>To use a Chromium you already have instead of the one Playwright downloads, set <code>PLAYWRIGHT_CHROMIUM_EXECUTABLE</code> to its path.</p><p>The public origin is <code>https://pidrang.dev</code>, set in <code>tools/demo-artifacts/shared.mjs</code> and in each demo&#39;s <code>environment.pages.ts</code>. Change all three places if the domain changes.</p>`,24)])])}const m=t(s,[["render",d]]);export{u as __pageData,m as default};
